-- What supabase/comment_pins.sql does, tried inside the rolled-back
-- transaction of a dry run: nothing here is kept.
--
--   set -a; . ./.env; set +a
--   PG_MODULE=/tmp/pg/node_modules/pg/lib/index.js \
--     node tools/apply_sql.mjs supabase/comment_pins.sql --dry \
--       --try=tools/comment_pins_try.sql --table=model_comments
--
-- After the live files. Made-up accounts, made and gone with the
-- transaction: Ada designs a tower; Bob pins a comment on one of its parts,
-- Cy comments on the whole model and replies to Bob. Each statement is on
-- one line: the dry run splits at a semicolon that ends a line.
create function pg_temp.tries(statement text) returns text language plpgsql as $$ begin execute statement; return 'allowed'; exception when others then return 'refused: ' || sqlerrm; end $$;
insert into auth.users (id, instance_id, aud, role, email) values ('00000000-0000-4000-8000-0000000009a1', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'pin-ada@resend.dev'), ('00000000-0000-4000-8000-0000000009b2', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'pin-bob@resend.dev'), ('00000000-0000-4000-8000-0000000009c3', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'pin-cy@resend.dev'), ('00000000-0000-4000-8000-0000000009d4', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'pin-kid@resend.dev');
select public.answer_age('00000000-0000-4000-8000-0000000009a1', true)->>'over_13' as ada, public.answer_age('00000000-0000-4000-8000-0000000009b2', true)->>'over_13' as bob, public.answer_age('00000000-0000-4000-8000-0000000009c3', true)->>'over_13' as cy, public.answer_age('00000000-0000-4000-8000-0000000009d4', false)->>'over_13' as kid;
insert into public.people (account, handle, name) values ('00000000-0000-4000-8000-0000000009a1', 'pin-try-ada', 'Ada Try'), ('00000000-0000-4000-8000-0000000009b2', 'pin-try-bob', 'Bob Try'), ('00000000-0000-4000-8000-0000000009c3', 'pin-try-cy', 'Cy Try');
insert into public.shared_models (id, owner, name, author, parts, bytes, listed, listed_at, test, created_at, has_image) values ('PinTry0001', '00000000-0000-4000-8000-0000000009a1', 'Try tower', 'Ada Try', 12, 100, true, now() - interval '3 days', true, now() - interval '3 days', true);
insert into public.share_versions (model, n, at, parts, bytes, steps) values ('PinTry0001', 1, now() - interval '3 days', 12, 100, 6);
-- A place that is not a part's: refused, and nothing written.
select public.add_pin('00000000-0000-4000-8000-0000000009b2', 'PinTry0001', 1, 4, 'Try: no part', null) as "no place", public.add_pin('00000000-0000-4000-8000-0000000009b2', 'PinTry0001', 1, 4, 'Try: no part', '{"part": "3001.dat", "colour": 4}') as "no at", public.add_pin('00000000-0000-4000-8000-0000000009b2', 'PinTry0001', 1, 4, 'Try: no part', '{"part": 3001, "colour": 4, "at": [0, 0, 0]}') as "a number for a part", public.add_pin('00000000-0000-4000-8000-0000000009b2', 'PinTry0001', 1, 4, 'Try: no part', '{"part": "3001.dat", "colour": 4, "at": ["a", 0, 0]}') as "words for where", public.add_pin('00000000-0000-4000-8000-0000000009b2', 'PinTry0001', 1, 4, 'Try: no part', '{"part": "3001.dat", "colour": 4, "at": {"x": 0}}') as "an object for where", public.add_pin('00000000-0000-4000-8000-0000000009b2', 'PinTry0001', 1, 4, 'Try: no part', '[1, 2]') as "a list", public.add_pin('00000000-0000-4000-8000-0000000009b2', 'PinTry0001', 1, 4, 'Try: no part', jsonb_build_object('part', '3001.dat', 'colour', 4, 'at', '[0,0,0]'::jsonb, 'near', repeat('x', 8100))) as "too long";
select count(*) as "written by those" from public.model_comments where model = 'PinTry0001';
-- Bob pins a comment on the 2 x 4 brick of step 4; Cy comments on the whole model and replies to Bob.
select r->'comment'->'pin'->>'part' as part, r->'comment'->>'step' as step, r->'comment'->>'resolved_at' as resolved_at, r->>'owner' = '00000000-0000-4000-8000-0000000009a1' as "tells Ada" from (select public.add_pin('00000000-0000-4000-8000-0000000009b2', 'PinTry0001', 1, 4, 'Try: this brick sits a plate high', '{"part": "3001.dat", "colour": 4, "at": [20, -24, 40], "turn": [1,0,0,0,1,0,0,0,1], "section": "", "line": 7, "near": [], "full": true, "with": []}') as r) x;
select public.add_comment('00000000-0000-4000-8000-0000000009c3', 'PinTry0001', 1, null, 'Try: lovely tower')->'comment'->>'pin' as "Cy's comment: pin";
select (r->'comment'->>'parent') is not null as "a reply", r->'comment'->>'pin' as "its pin" from (select public.add_reply('00000000-0000-4000-8000-0000000009c3', (select id from public.model_comments where body = 'Try: this brick sits a plate high'), 'Try: agreed') as r) x;
-- The rules of a comment hold: under 13, nobody, a model it is not on.
select public.add_pin('00000000-0000-4000-8000-0000000009d4', 'PinTry0001', 1, null, 'Try: kid', '{"part": "3001.dat", "colour": 4, "at": [0, 0, 0]}') as "under 13", public.add_pin(null, 'PinTry0001', 1, null, 'Try: nobody', '{"part": "3001.dat", "colour": 4, "at": [0, 0, 0]}') as nobody, public.add_pin('00000000-0000-4000-8000-0000000009b2', 'PinTry0001', 2, null, 'Try: v2', '{"part": "3001.dat", "colour": 4, "at": [0, 0, 0]}') as "a version it has not";
-- What everybody reads: the pin on Bob's comment, none on Cy's or the reply, and pins: true.
select c->>'body' as body, c->'pin'->>'part' as part, c->'pin'->>'line' as line, c->>'resolved_at' as resolved_at from jsonb_array_elements(public.comments_on('PinTry0001')->'comments') c order by c->>'id';
select public.comments_on('PinTry0001')->>'pins' as pins, public.comments_on('PinTry0001')->>'threads' as threads;
-- A pin stays as it was written, whatever writes; a reply is never one; resolved only with a pin.
select pg_temp.tries($q$update public.model_comments set pin = '{"part": "3002.dat", "colour": 1, "at": [0, 0, 0]}' where body = 'Try: this brick sits a plate high'$q$) as "moving Bob's pin", pg_temp.tries($q$update public.model_comments set pin = null where body = 'Try: this brick sits a plate high'$q$) as "taking it off";
select pg_temp.tries($q$update public.model_comments set pin = '{"part": "3002.dat", "colour": 1, "at": [0, 0, 0]}' where body = 'Try: agreed'$q$) as "a pin on the reply";
select pg_temp.tries($q$update public.model_comments set at = now() - interval '1 hour' where body = 'Try: lovely tower'$q$) as "an old comment's time", pg_temp.tries($q$update public.model_comments set pin = '{"part": "3002.dat", "colour": 1, "at": [0, 0, 0]}' where body = 'Try: lovely tower'$q$) as "a pin on an old comment";
select pg_temp.tries($q$update public.model_comments set resolved_at = now() where body = 'Try: lovely tower'$q$) as "resolving no pin";
select pg_temp.tries($q$insert into public.model_comments (model, version, author, body, pin) values ('PinTry0001', 1, '00000000-0000-4000-8000-0000000009c3', 'Try: written directly', '{"part": "3002.dat", "colour": 1}')$q$) as "a place with no at, written directly", pg_temp.tries($q$insert into public.model_comments (model, version, author, body, pin) values ('PinTry0001', 1, '00000000-0000-4000-8000-0000000009c3', 'Try: written directly 2', '{"part": "3002.dat", "colour": 1, "at": [0, 0, 0]}')$q$) as "a whole place, written directly";
-- Resolve: Ada alone, on a pin; and open again.
select public.resolve_pin('00000000-0000-4000-8000-0000000009b2', (select id from public.model_comments where body = 'Try: this brick sits a plate high'), true) as "Bob resolves", public.resolve_pin('00000000-0000-4000-8000-0000000009a1', (select id from public.model_comments where body = 'Try: lovely tower'), true) as "Ada resolves no pin", public.resolve_pin(null, (select id from public.model_comments where body = 'Try: this brick sits a plate high'), true) as "nobody resolves";
select (r->'comment'->>'resolved_at') is not null as resolved, r->'comment'->'pin'->>'part' as part from (select public.resolve_pin('00000000-0000-4000-8000-0000000009a1', (select id from public.model_comments where body = 'Try: this brick sits a plate high'), true) as r) x;
select c->>'body' as body, (c->>'resolved_at') is not null as "everybody reads it resolved" from jsonb_array_elements(public.comments_on('PinTry0001')->'comments') c where c->'pin' <> 'null'::jsonb;
select public.comment_pins_of(array(select id from public.model_comments where model = 'PinTry0001' order by id)) as "pins of the model's comments";
select (r->'comment'->>'resolved_at') is null as "open again" from (select public.resolve_pin('00000000-0000-4000-8000-0000000009a1', (select id from public.model_comments where body = 'Try: this brick sits a plate high'), false) as r) x;
-- A removed pin is not resolved, nor listed.
update public.model_comments set removed_at = now(), removed_by = 'author' where body = 'Try: this brick sits a plate high';
select public.resolve_pin('00000000-0000-4000-8000-0000000009a1', (select id from public.model_comments where body = 'Try: this brick sits a plate high'), true) as "resolving a removed pin";
-- Nobody but the server.
select has_function_privilege('anon', 'public.add_pin(uuid, text, integer, integer, text, jsonb)', 'execute') as anon_pins, has_function_privilege('authenticated', 'public.resolve_pin(uuid, bigint, boolean)', 'execute') as signed_in_resolves, has_function_privilege('authenticated', 'public.comment_pins_of(bigint[])', 'execute') as signed_in_reads, has_function_privilege('service_role', 'public.add_pin(uuid, text, integer, integer, text, jsonb)', 'execute') as server_pins, has_function_privilege('service_role', 'public.resolve_pin(uuid, bigint, boolean)', 'execute') as server_resolves;
